  "2026-10-07|19:15": [
    {
      name: "Toward a Child & Family Centered Society: Equity and Innovative Transformation in Asia",
      code: "TOWA2679",
      type: "strategy",
      theme: "Systems Innovation and the Architecture of Change",
      endTime: "20:45",
      tags: ["international perspectives","storytelling","child protection","children/youth voice","system transformation","policy"],
      description: "Rapid technological, demographic, and educational changes drive welfare transformation in Asia. Focused on the turn to child-centric practices and stakeholder voice, this Strategy Session features a series of case studies on system innovation and grassroots change to better understand how child welfare professionals are designing equitable initiatives amidst myriad social pressures. By uniting professionals and practitioners across Japan, Taiwan, and Singapore, our panel offers detailed cross-cultural findings and interdisciplinary insights for improving care equity and well-being. The panel will also reflect on the positionality of social workers and the challenges they face as new scientific-technological ideas take root in child welfare practice.",
      speakers: [
        { name: "Chris Chapman", title: "Assistant Professor of Social Sciences", org: "Nanyang Technological University", bio: "Christopher Chapman is an ethnographer based in the School of Social Sciences at Nanyang Technological University. He is broadly interested in health and medicine in the Asia-Pacific, particularly in how people care for each other and how these practices intersect with social service and biomedical systems. His current research focuses on the mobilization of psychiatric and developmental science within the lives of marginalized children and their families." },
        { name: "Yu-Wen Chen", title: "Professor of Social Work", org: "National Taiwan University", bio: "Yu-Wen Chen is a Professor in the Department of Social Work at National Taiwan University, where she has taught since 1996. Her research focuses on disadvantaged youth, family welfare, and children’s well-being, with a strong emphasis on children’s rights and social policy. She leads Taiwan’s participation in the global ISCWeB (International Survey of Children’s Well-Being) project and co-leads international research on intercountry adoption, contributing to cross-national scholarship on child welfare. In recent years, her research has expanded to include energy poverty, examining its social impacts on vulnerable families and children, and highlighting its implications for inequality and well-being. Through both qualitative and quantitative approaches, her research has informed welfare policy development and played a key role in advancing the discourse on children’s rights, social justice, and family well-being in Taiwan and beyond." },
        { name: "Yukako Hatakeyama", title: "Professor of Social Work", org: "Kwansei Gakuin University", bio: "Yukako Hatakeyama is a social welfare professor and social worker who has dedicated herself to raising awareness of child welfare innovations among Japanese academics and leaders. Her research examines families' involvement in casework decision-making. She also conducts cross-cultural comparison studies between Japan, the U.S., and France. She earned her Ph.D. from Kwansei Gakuin University and MSW from the University of Chicago as a Fulbright Scholar. She is based in the School of Human Welfare Studies, Kwansei Gakuin University." },
        { name: "Ching-Hsuan Lin", title: "Associate Professor of Social Work", org: "National Taiwan University", bio: "Ching-Hsuan Lin is an Associate Professor in the Department of Social Work at National Taiwan University. His research focuses on child protection, out-of-home care, adoption support, trauma-informed practice, and the well-being of families and children, with particular attention to the child welfare systems in Taiwan. He is currently involved in multiple research projects, including studies on kinship caregivers perspectives on support needs, the systemic transformation of foster family services, youths’ voices on relational permanency and normalcy in residential care, the prevalence of child maltreatment in Taiwan, post-adoption support in intercountry adoption, and the application of trauma-informed practice in family intervention programs." },
        { name: "Saki Nagano", title: "Associate Professor of Social Welfare", org: "Musashino University", bio: "Saki Nagano is an Associate Professor in the Department of Social Welfare at Musashino University. She earned her Ph.D. from Toyo University and is currently the President of International Foster Care Alliance - Japan, an NPO that promotes youth participation in social care. Her work focuses on both research and practice related to the participation of young people with lived experience in out-of-home care, as well as empirical studies on the living conditions of care leavers. Her doctoral dissertation examined the life chances of care-experienced youth through both qualitative and quantitative analyses and was highly acclaimed." },
        { name: "Michelle Tan", title: "Executive Director", org: "Gladiolus Place", bio: "Michelle Tan has been the Executive Director and Head of Home at Gladiolus Place Children’s Home since 2018. Over the course of her tenure, Michelle has built an organisation and a safe residential care facility for 45 displaced teenage Girls aged 10-21 with child protection concerns. Today, Gladiolus Place provides round-the-clock trauma-informed care to each of the beneficiaries, with a full suite of case management and counselling services, family reintegration work, as well as curated and targeted programmes to ensure that beneficiaries continue to be enriched, be developed holistically, and flourish in a family, home-like environment. Committed to nurturing the next generation of social service professionals, Michelle has supervised interns and trainees from five publicly funded universities in Singapore. She is also a part-time teaching staff with two of these universities, with whom she conducts fieldwork education and field supervision for trainee social workers and counsellors" }
      ]
    }
  ],
